window.ODE.cardDeck = [{"id":"c1","cat":"§1 基本觀念","q":"ODE 與 PDE 的差別？（英文全名）","a":"ODE = <b>Ordinary<\/b> DE，未知函數只依賴<b>一個<\/b>自變數；PDE = <b>Partial<\/b> DE，依賴兩個以上。"},{"id":"c2","cat":"§1 基本觀念","q":"「階 (order)」與「次 (degree)」怎麼看？","a":"階 = 最高階導數的階數。次 = <b>那個最高階導數<\/b>的次方（要先去掉根號／分數）。"},{"id":"c3","cat":"§1 基本觀念","q":"判斷線性的三個條件？","a":"① \\(y\\) 與各階導數都只出現一次方；② 係數只能含 \\(x\\)；③ \\(y\\) 不能出現在 \\(\\sin/\\cos/e^{\\Box}/\\ln\\) 裡面。"},{"id":"c4","cat":"§1 基本觀念","q":"通解 / 特解 / 奇異解 各是什麼？","a":"通解：含 \\(n\\) 個獨立任意常數。特解：常數被初值定住。奇異解：<b>不能<\/b>由通解選常數得到。"},{"id":"c5","cat":"§1 基本觀念","q":"IVP 的條件數怎麼配？","a":"<b>幾個常數配幾個條件<\/b>：一階 → 1 個；二階 → 2 個（\\(y(x_0)\\) 與 \\(y'(x_0)\\)）。"},{"id":"c6","cat":"§2 可分離","q":"可分離方程的標準形式與解法？","a":"\\(g(y)y'=f(x)\\) 或 \\(\\dfrac{dy}{dx}=\\dfrac{f(x)}{g(y)}\\) → 分離成 \\(g(y)dy=f(x)dx\\) 後兩邊積分。"},{"id":"c7","cat":"§2 可分離","q":"分離變數時最容易漏掉什麼？","a":"<b>除以含 \\(y\\) 的式子時弄丟的常數解<\/b>（例如 \\(y'=y(1-y)\\) 的 \\(y\\equiv0\\) 與 \\(y\\equiv1\\)）。"},{"id":"c8","cat":"§2 可分離","q":"\\(y'=f(ax+by+c)\\) 型要用什麼代換？","a":"令 \\(u=ax+by+c\\) → \\(u'=a+bf(u)\\)，化為可分離。"},{"id":"c9","cat":"§2 可分離","q":"齊次型 \\(y'=f(y/x)\\) 要用什麼代換？","a":"令 \\(u=y/x\\)（即 \\(y=ux\\)，\\(y'=u+xu'\\)）→ \\(xu'=f(u)-u\\)，可分離。注意這個「齊次」和齊次線性方程是不同意思。"},{"id":"c10","cat":"§3 正合","q":"正合的判準與解的意義？","a":"\\(\\dfrac{\\partial M}{\\partial y}=\\dfrac{\\partial N}{\\partial x}\\)。此時 \\(\\exists F\\) 使 \\(dF=M dx+N dy\\)，解就是 \\(F(x,y)=c\\)（等值線）。"},{"id":"c11","cat":"§3 正合","q":"求 \\(F\\) 的標準流程？","a":"\\(F=\\int M\\,dx+k(y)\\) → \\(F_y=\\dfrac{\\partial}{\\partial y}\\int M\\,dx+k'(y)\\overset{!}{=}N\\) → 解出 \\(k'(y)\\) → 積分。"},{"id":"c12","cat":"§3 正合","q":"兩個積分因子公式（只含 x / 只含 y）？","a":"只含 \\(x\\)：\\(\\dfrac{M_y-N_x}{N}=R(x)\\Rightarrow\\mu=e^{\\int R\\,dx}\\)。只含 \\(y\\)：\\(\\dfrac{N_x-M_y}{M}=S(y)\\Rightarrow\\mu=e^{\\int S\\,dy}\\)。"},{"id":"c13","cat":"§4 一階線性","q":"一階線性方程的標準形與公式？","a":"\\(y'+p(x)y=r(x)\\)，\\(\\mu=e^{\\int p\\,dx}\\)，\\(y=\\dfrac{1}{\\mu}\\left(\\int\\mu r\\,dx+C\\right)\\)。"},{"id":"c14","cat":"§4 一階線性","q":"套公式前一定要先做什麼？","a":"<b>把 \\(y'\\) 的係數除成 1<\/b>（化成標準形）。例如 \\(xy'-2y=x^{4}\\) 要先除以 \\(x\\)。"},{"id":"c15","cat":"§4 一階線性","q":"解的結構是什麼？","a":"\\(y=y_h+y_p\\)：\\(y_h=Ce^{-\\int p\\,dx}\\)（齊次解），\\(y_p\\) 是一個特解。"},{"id":"c16","cat":"§4 一階線性","q":"Bernoulli 方程 \\(y'+py=gy^{a}\\) 怎麼解？","a":"令 \\(u=y^{1-a}\\) → 化為一階線性 → 解出 \\(u\\) → 換回 \\(y\\) → 別忘了補 \\(y\\equiv0\\)。"},{"id":"c17","cat":"§5 二階齊次線性","q":"Wronskian 的定義與判準？","a":"\\(W=y_1y_2'-y_2y_1'\\)。<b>\\(W\\equiv0\\) → 線性相依；只要有一點 \\(W\\neq0\\) → 獨立<\/b>。"},{"id":"c18","cat":"§5 二階齊次線性","q":"Abel 公式？","a":"\\(W(x)=W_0e^{-\\int p\\,dx}\\)。因為指數函數恆正，所以 \\(W\\) 只有「恆 0」或「處處非 0」兩種。"},{"id":"c19","cat":"§5 二階齊次線性","q":"降階公式（已知 \\(y_1\\) 求 \\(y_2\\)）？","a":"\\(y_2=y_1\\displaystyle\\int\\frac{e^{-\\int p\\,dx}}{y_1^{2}}dx\\)，其中 \\(p\\) 是<b>標準形<\/b>中 \\(y'\\) 的係數。"},{"id":"c20","cat":"§5 二階齊次線性","q":"疊加原理 (superposition)？","a":"齊次線性方程的解可以相加、乘常數：\\ \\(c_1y_1+c_2y_2\\) 還是解。非齊次方程不成立。"},{"id":"c21","cat":"§6 常係數","q":"常係數二階齊次的三種情況？","a":"① 相異實根：\\(c_1e^{\\lambda_1x}+c_2e^{\\lambda_2x}\\)；② 重根：\\((c_1+c_2x)e^{\\lambda x}\\)；③ 複根 \\(\\alpha\\pm\\beta i\\)：\\(e^{\\alpha x}(c_1\\cos\\beta x+c_2\\sin\\beta x)\\)。"},{"id":"c22","cat":"§6 常係數","q":"怎麼用判別式快速判型態？","a":"\\(\\Delta=a^{2}-4b\\)：\\(\\Delta>0\\) 相異實根；\\(\\Delta=0\\) 重根；\\(\\Delta<0\\) 複根（振盪）。"},{"id":"c23","cat":"§6 常係數","q":"物理對應：過阻尼 / 臨界阻尼 / 欠阻尼？","a":"\\(\\Delta>0\\) 過阻尼；\\(\\Delta=0\\) 臨界阻尼（最快回平衡不越過）；\\(\\Delta<0\\) 欠阻尼（阻尼振盪）。"},{"id":"c24","cat":"§6 常係數","q":"阻尼比與頻率的關係？","a":"\\(\\zeta=\\dfrac{c}{2\\sqrt{mk}}\\)，\\(\\omega_0=\\sqrt{k/m}\\)，\\(\\omega_d=\\omega_0\\sqrt{1-\\zeta^{2}}\\)。特徵根 \\(=-\\zeta\\omega_0\\pm i\\omega_d\\)。"},{"id":"c25","cat":"§7 Euler–Cauchy","q":"Euler 方程與指標方程？","a":"\\(x^{2}y''+axy'+by=0\\)，試驗解 \\(y=x^{m}\\)，指標方程 \\(m(m-1)+am+b=0\\)（即 \\(m^{2}+(a-1)m+b=0\\)）。"},{"id":"c26","cat":"§7 Euler–Cauchy","q":"Euler 方程的三種情況？","a":"① \\(m\\) 相異實：\\(c_1x^{m_1}+c_2x^{m_2}\\)；② 重根：\\((c_1+c_2\\ln x)x^{m}\\)；③ \\(m=\\alpha\\pm\\beta i\\)：\\(x^{\\alpha}[c_1\\cos(\\beta\\ln x)+c_2\\sin(\\beta\\ln x)]\\)。"},{"id":"c27","cat":"§7 Euler–Cauchy","q":"\\(x=e^{t}\\) 代換後方程變成什麼？","a":"\\(\\ddot y+(a-1)\\dot y+by=0\\)。\\ \\(x\\leftrightarrow e^{t}\\)、\\(\\ln x\\leftrightarrow t\\) —— 這就是兩章公式一一對應的原因。"},{"id":"c28","cat":"§7 Euler–Cauchy","q":"\\(x<0\\) 時要注意什麼？","a":"分數冪在 \\(x<0\\) 沒有實數定義，所以一般寫 \\(|x|^{m}\\)（或把 \\(x>0\\)、\\(x<0\\) 分開講）。\\(x=0\\) 是奇點。"},{"id":"c29","cat":"§8 存在唯一","q":"Picard–Lindelöf 定理的條件與結論？","a":"\\(f\\) 與 \\(\\dfrac{\\partial f}{\\partial y}\\) 在矩形 \\(R\\) 上連續 → IVP 在 \\(|x-x_0|\\le h\\) 上恰有一解，\\(h=\\min\\left(a,\\dfrac{b}{M}\\right)\\)，\\(M=\\max_R|f|\\)。"},{"id":"c30","cat":"§8 存在唯一","q":"連續與 Lipschitz 各保證什麼？","a":"\\(f\\) 連續 → <b>存在<\/b>（Peano）；再加 \\(\\partial f/\\partial y\\) 有界（Lipschitz）→ <b>唯一<\/b>。"},{"id":"c31","cat":"§8 存在唯一","q":"唯一性壞掉的經典反例？","a":"\\(y'=y^{2/3}\\)（或 \\(\\sqrt{|y|}\\)）在 \\(y_0=0\\)：\\(\\partial f/\\partial y\\) 在 \\(y=0\\) 無界 → 不唯一（\\(y\\equiv0\\) 與 \\(y=x^{3}/27\\) 都是解）。"},{"id":"c32","cat":"§8 存在唯一","q":"二階線性方程的存在唯一性定理？","a":"\\(p,q\\) 在含 \\(x_0\\) 的開區間 \\(I\\) 上連續 → IVP 在<b>整個 \\(I\\)<\/b> 上恰有一解。區間不能跨過奇點。"}];
